        @php
            $priceButtonLink=$safeUrl($settings['buttonLink']??'');
            $priceButtonMeta=$linkMeta($settings,'buttonLink');
            $priceFormat=$settings['currencyFormat']??'comma';
            $formatPrice=function($value) use ($priceFormat): string {
                $raw=trim((string)$value);
                $normalized=preg_replace('/[^\d.-]/','',$raw);
                if(!is_numeric($normalized)) return $raw;
                $decimals=str_contains($normalized,'.')?min(2,strlen(substr(strrchr($normalized,'.'),1))):0;
                return number_format((float)$normalized,$decimals,$priceFormat==='period'?',':'.',$priceFormat==='period'?'.':',');
            };
